  const rowStyle = { width: totalWidth, minWidth: "100%", height: rowHeight };

  return (
    <div
      className={cx(
        "relative overflow-hidden border border-[var(--rd-color-border-default)] rounded-[var(--rd-radius-overlay)] " +
